entries[1264988] = { ["name"] = "Schneepfotenglimmerpelzstreuner", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Schneepfoten bewohnen die kalten Nachleben der Schattenlande und genießen ihre frostige Umgebung. Reisende, die den tödlichen Schneestürmen von Nordend verloren geglaubt waren, wurden manchmal wundersamerweise lebendig aufgefunden. Sie erzählten dabei, dass sie ihre Leben den geheimnisvollen Füchsen verdankten, die sie beschützt hatten.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000" }
entries[1265009] = { ["name"] = "Todesgriff", ["text"] = "30 Meter Reichweite\nSofort 1 sek. Abklingzeit\nMacht sich die unheilige Energie, die alle Materie umgibt und verbindet, zunutze und zieht das Ziel zum Zaubernden hin." }
